//! Replays `tests/vectors/sig-v1.json` (generated by `gen.py`) against the encoder.

use cainary_sig::{Domain, EncodeError, Key, Value, encode, message, sha256_hex, sign};

#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Num(u64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

struct Reader<'a> {
    b: &'a [u8],
    i: usize,
}

impl Reader<'_> {
    fn ws(&mut self) {
        while self.i < self.b.len() && self.b[self.i].is_ascii_whitespace() {
            self.i += 1;
        }
    }

    fn eat(&mut self, c: u8) {
        self.ws();
        assert_eq!(self.b[self.i], c, "expected {:?} at {}", c as char, self.i);
        self.i += 1;
    }

    fn lit(&mut self, word: &str) {
        assert!(self.b[self.i..].starts_with(word.as_bytes()));
        self.i += word.len();
    }

    fn value(&mut self) -> Json {
        self.ws();
        match self.b[self.i] {
            b'n' => {
                self.lit("null");
                Json::Null
            }
            b't' => {
                self.lit("true");
                Json::Bool(true)
            }
            b'f' => {
                self.lit("false");
                Json::Bool(false)
            }
            b'"' => Json::Str(self.string()),
            b'[' => {
                self.i += 1;
                let mut v = Vec::new();
                self.ws();
                if self.b[self.i] == b']' {
                    self.i += 1;
                    return Json::Arr(v);
                }
                loop {
                    v.push(self.value());
                    self.ws();
                    match self.b[self.i] {
                        b',' => self.i += 1,
                        b']' => {
                            self.i += 1;
                            return Json::Arr(v);
                        }
                        c => panic!("bad array separator {:?}", c as char),
                    }
                }
            }
            b'{' => {
                self.i += 1;
                let mut v = Vec::new();
                self.ws();
                if self.b[self.i] == b'}' {
                    self.i += 1;
                    return Json::Obj(v);
                }
                loop {
                    self.ws();
                    let k = self.string();
                    self.eat(b':');
                    v.push((k, self.value()));
                    self.ws();
                    match self.b[self.i] {
                        b',' => self.i += 1,
                        b'}' => {
                            self.i += 1;
                            return Json::Obj(v);
                        }
                        c => panic!("bad object separator {:?}", c as char),
                    }
                }
            }
            b'0'..=b'9' => {
                let start = self.i;
                while self.b[self.i].is_ascii_digit() {
                    self.i += 1;
                }
                Json::Num(
                    std::str::from_utf8(&self.b[start..self.i])
                        .unwrap()
                        .parse()
                        .unwrap(),
                )
            }
            c => panic!("unexpected {:?}", c as char),
        }
    }

    fn string(&mut self) -> String {
        assert_eq!(self.b[self.i], b'"');
        self.i += 1;
        let mut out: Vec<u8> = Vec::new();
        loop {
            let c = self.b[self.i];
            self.i += 1;
            match c {
                b'"' => return String::from_utf8(out).unwrap(),
                b'\\' => {
                    let e = self.b[self.i];
                    self.i += 1;
                    match e {
                        b'"' | b'\\' | b'/' => out.push(e),
                        b'n' => out.push(b'\n'),
                        b't' => out.push(b'\t'),
                        b'r' => out.push(b'\r'),
                        b'u' => {
                            let mut cp = self.hex4();
                            if (0xd800..0xdc00).contains(&cp) {
                                assert_eq!(&self.b[self.i..self.i + 2], b"\\u");
                                self.i += 2;
                                let lo = self.hex4();
                                cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
                            }
                            let ch = char::from_u32(cp).unwrap();
                            out.extend_from_slice(ch.to_string().as_bytes());
                        }
                        _ => panic!("bad escape"),
                    }
                }
                _ => out.push(c),
            }
        }
    }

    fn hex4(&mut self) -> u32 {
        let h = std::str::from_utf8(&self.b[self.i..self.i + 4]).unwrap();
        self.i += 4;
        u32::from_str_radix(h, 16).unwrap()
    }
}

fn get<'a>(obj: &'a Json, key: &str) -> &'a Json {
    let Json::Obj(pairs) = obj else {
        panic!("not an object")
    };
    pairs
        .iter()
        .find(|(k, _)| k == key)
        .map_or(&Json::Null, |(_, v)| v)
}

fn str_of(j: &Json) -> &str {
    let Json::Str(s) = j else {
        panic!("not a string")
    };
    s
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

fn typed(j: &Json) -> Value {
    let v = || get(j, "v");
    match str_of(get(j, "t")) {
        "absent" => Value::Absent,
        "null" => Value::Null,
        "bool" => match v() {
            Json::Bool(b) => Value::Bool(*b),
            _ => panic!("bool"),
        },
        "u64" => Value::U64(str_of(v()).parse().unwrap()),
        "i64" => Value::I64(str_of(v()).parse().unwrap()),
        "bytes_repeat" => {
            let Json::Num(count) = get(j, "count") else {
                panic!("count")
            };
            Value::Bytes(unhex(str_of(get(j, "byte"))).repeat(*count as usize))
        }
        "bytes" => Value::Bytes(unhex(str_of(v()))),
        "str" => Value::Str(str_of(v()).to_string()),
        "list" => {
            let Json::Arr(items) = v() else {
                panic!("list")
            };
            Value::List(items.iter().map(typed).collect())
        }
        "map" => Value::Map(map_pairs(v())),
        t => panic!("unknown type {t}"),
    }
}

fn map_pairs(j: &Json) -> Vec<(String, Value)> {
    let Json::Arr(pairs) = j else { panic!("map") };
    pairs
        .iter()
        .map(|p| {
            let Json::Arr(kv) = p else { panic!("pair") };
            (str_of(&kv[0]).to_string(), typed(&kv[1]))
        })
        .collect()
}

#[test]
fn vectors_match() {
    let text = include_str!("vectors/sig-v1.json");
    let Json::Arr(cases) = (Reader {
        b: text.as_bytes(),
        i: 0,
    })
    .value() else {
        panic!("vectors must be an array")
    };
    assert!(cases.len() >= 8);
    let mut signed = 0;
    let mut rejected = 0;
    for case in &cases {
        let name = str_of(get(case, "name"));
        let fields = get(case, "fields");
        if let Json::Str(want) = get(case, "expect_error") {
            let got = match encode(&typed(fields)) {
                Err(EncodeError::DuplicateKey(_)) => "duplicate-key",
                Err(EncodeError::TooDeep) => "too-deep",
                Err(EncodeError::TooLarge) => "too-large",
                Ok(_) => "ok",
            };
            assert_eq!(got, want, "{name}");
            rejected += 1;
            continue;
        }
        if matches!(get(case, "encoding_hex"), Json::Null) {
            let bytes = encode(&typed(fields)).unwrap();
            let Json::Num(len) = get(case, "encoding_len") else {
                panic!("{name}: len")
            };
            assert_eq!(bytes.len() as u64, *len, "{name}: length");
            assert_eq!(
                sha256_hex(&bytes),
                str_of(get(case, "encoding_sha256_hex")),
                "{name}"
            );
            continue;
        }
        let expected = str_of(get(case, "encoding_hex"));
        match get(case, "domain") {
            Json::Null => {
                assert_eq!(hex(&encode(&typed(fields)).unwrap()), expected, "{name}");
                assert!(matches!(get(case, "digest_hex"), Json::Null), "{name}");
            }
            d => {
                let domain = Domain::from_name(str_of(d)).expect(name);
                let Json::Str(key_hex) = get(case, "key_hex") else {
                    panic!("{name}: signing case needs a key")
                };
                let key: [u8; 32] = unhex(key_hex).try_into().unwrap();
                let key = Key::from_bytes(key);
                let pairs = map_pairs(get(fields, "v"));
                assert_eq!(
                    hex(&message(domain, pairs).unwrap()),
                    expected,
                    "{name}: message"
                );
                let pairs = map_pairs(get(fields, "v"));
                let digest = sign(&key, domain, pairs).unwrap();
                assert_eq!(
                    digest.hex(),
                    str_of(get(case, "digest_hex")),
                    "{name}: digest"
                );
                signed += 1;
            }
        }
    }
    assert!(signed >= 2);
    assert!(rejected >= 5);
}
